        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans provide the independent timing agreement, return-specific example, comparison across bookings and explicit causal limit."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C003.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
